T.Translations("deDE", {
  ["Mail"] = "Post",
  ["At the mailbox: open all your mail at once (or only the gold), pick a recent name or one of your characters for the To box, and Alt-click a bag item to attach every stack of it."] = "Am Briefkasten: öffne deine ganze Post auf einmal (oder nur das Gold), wähle einen kürzlich benutzten Namen oder einen deiner Charaktere für das Empfängerfeld und hänge mit Alt-Klick auf einen Gegenstand in der Tasche jeden Stapel davon an.",
  ["Open all"] = "Alle öffnen",
  ["Gold only"] = "Nur Gold",
  ["Open all (Codex)"] = "Alle öffnen (Codex)",
  ["Gold only (Codex)"] = "Nur Gold (Codex)",
  ["Stops taking mail."] = "Hört auf, Post zu nehmen.",
  ["Takes the gold and items from every mail, one after the other. Mails with Cash on Delivery and mails from a Game Master are left for you to open. With full bags the gold is still taken."] = "Nimmt das Gold und die Gegenstände aus jedem Brief, einen nach dem anderen. Briefe per Nachnahme und Briefe von einem Spielleiter bleiben, damit du sie selbst öffnest. Mit vollen Taschen wird das Gold trotzdem genommen.",
  ["Takes the gold from every mail and leaves the items in the mail."] = "Nimmt das Gold aus jedem Brief und lässt die Gegenstände in der Post.",
  ["Recent names (Codex)"] = "Letzte Namen (Codex)",
  ["The names you sent mail to on this realm, and your other characters here. Click one to put it in the To box."] = "Die Namen, denen du auf diesem Realm Post geschickt hast, und deine anderen Charaktere hier. Klick einen an, um ihn ins Empfängerfeld zu setzen.",
  ["Recent"] = "Zuletzt",
  ["Your characters"] = "Deine Charaktere",
  ["No names yet: the names you send mail to show here."] = "Noch keine Namen: Hier stehen die Namen, denen du Post schickst.",
  ["Forget the recent names"] = "Letzte Namen vergessen",
  ["Open all: took %s and %d items."] = "Alle öffnen: %s und %d Gegenstände genommen.",
  ["Open all: took %s."] = "Alle öffnen: %s genommen.",
  ["Open all: took %d items."] = "Alle öffnen: %d Gegenstände genommen.",
  ["Open all: nothing to take."] = "Alle öffnen: Nichts zu nehmen.",
  ["Stopped: the mailbox closed."] = "Angehalten: Der Briefkasten wurde geschlossen.",
  ["Stopped."] = "Angehalten.",
  ["Your bags are full: the rest of the items wait in the mail."] = "Deine Taschen sind voll: Die übrigen Gegenstände warten in der Post.",
  ["Mails with Cash on Delivery are left for you to open: %d."] = "Briefe per Nachnahme, die du selbst öffnen musst: %d.",
  ["Attached 1 stack of %s."] = "1 Stapel %s angehängt.",
  ["Attached %d stacks of %s."] = "%d Stapel %s angehängt.",
  ["The letter is full; the rest stays in your bags."] = "Der Brief ist voll; der Rest bleibt in deinen Taschen.",
  ["Postal is loaded: Codex leaves the mailbox to it."] = "Postal ist geladen: Codex überlässt ihm den Briefkasten.",
  ["Every part is switched off below."] = "Unten ist jeder Teil ausgeschaltet.",
  ["On at the mailbox."] = "Am Briefkasten an.",
  ["Open all and Gold only buttons in the inbox"] = "Schaltflächen Alle öffnen und Nur Gold im Posteingang",
  ["Two buttons take the place of the game's Open All Mail: Open all takes the gold and items from every mail, Gold only just the gold. Mails with Cash on Delivery and mails from a Game Master are left for you. With full bags the gold is still taken. One line in chat tells what you got."] = "Zwei Schaltflächen ersetzen die des Spiels zum Öffnen aller Post: Alle öffnen nimmt Gold und Gegenstände aus jedem Brief, Nur Gold nur das Gold. Briefe per Nachnahme und von einem Spielleiter bleiben für dich. Mit vollen Taschen wird das Gold trotzdem genommen. Eine Zeile im Chat sagt, was du bekommen hast.",
  ["Recent names beside the To box"] = "Letzte Namen am Empfängerfeld",
  ["A small button at the end of the To box lists the names you sent mail to on this realm and your other characters here. Click one to put it in the To box."] = "Eine kleine Schaltfläche am Ende des Empfängerfelds zeigt die Namen, denen du auf diesem Realm Post geschickt hast, und deine anderen Charaktere hier. Klick einen an, um ihn ins Empfängerfeld zu setzen.",
  ["Alt-click a bag item to attach every stack of it"] = "Alt-Klick auf einen Gegenstand hängt jeden Stapel davon an",
  ["While the Send Mail tab is open, Alt-click an item in your bags and every stack of it goes into the letter, up to its 12 slots. Soulbound items stay in your bags."] = "Während der Reiter Post verschicken offen ist, kommt mit Alt-Klick auf einen Gegenstand in deinen Taschen jeder Stapel davon in den Brief, bis zu seinen 12 Plätzen. Seelengebundene Gegenstände bleiben in deinen Taschen.",
  ["Recent names on this realm: %d."] = "Letzte Namen auf diesem Realm: %d.",
  ["No recent names on this realm yet."] = "Noch keine letzten Namen auf diesem Realm.",
  ["At the mailbox Codex takes all your mail at once (or only the gold), remembers the names you send mail to, and attaches every stack of an item with one Alt-click. Nothing is sent by itself: you still press Send."] = "Am Briefkasten nimmt Codex deine ganze Post auf einmal (oder nur das Gold), merkt sich die Namen, denen du Post schickst, und hängt mit einem Alt-Klick jeden Stapel eines Gegenstands an. Nichts wird von selbst verschickt: Senden drückst du weiter selbst.",
  ["Postal is loaded: it does these jobs, so Codex leaves the mailbox to it."] = "Postal ist geladen: Es erledigt diese Aufgaben, darum überlässt Codex ihm den Briefkasten.",
  ["Clears the list of names you sent mail to on this realm. Your characters stay."] = "Leert die Liste der Namen, denen du auf diesem Realm Post geschickt hast. Deine Charaktere bleiben.",
})

