  ["The names you sent mail to on this realm, and your other characters here. Click one to put it in the To box."] = "Os nomes para quem você enviou correio neste reino e seus outros personagens aqui. Clique em um para colocá-lo como destinatário.",
  ["Recent"] = "Recentes",
  ["Your characters"] = "Seus personagens",
  ["No names yet: the names you send mail to show here."] = "Nenhum nome ainda: os nomes para quem você envia correio aparecem aqui.",
  ["Forget the recent names"] = "Esquecer os nomes recentes",
  ["Open all: took %s and %d items."] = "Abrir tudo: %s e %d itens pegos.",
  ["Open all: took %s."] = "Abrir tudo: %s pego.",
  ["Open all: took %d items."] = "Abrir tudo: %d itens pegos.",
  ["Open all: nothing to take."] = "Abrir tudo: nada para pegar.",
  ["Stopped: the mailbox closed."] = "Parado: a caixa de correio fechou.",
  ["Stopped."] = "Parado.",
  ["Your bags are full: the rest of the items wait in the mail."] = "Suas bolsas estão cheias: o resto dos itens espera no correio.",
  ["Mails with Cash on Delivery are left for you to open: %d."] = "Cartas com pagamento na entrega deixadas para você abrir: %d.",
  ["Attached 1 stack of %s."] = "1 pilha de %s anexada.",
  ["Attached %d stacks of %s."] = "%d pilhas de %s anexadas.",
  ["The letter is full; the rest stays in your bags."] = "A carta está cheia; o resto fica nas suas bolsas.",
  ["Postal is loaded: Codex leaves the mailbox to it."] = "O Postal está carregado: o Codex deixa a caixa de correio com ele.",
  ["Every part is switched off below."] = "Todas as partes estão desligadas abaixo.",
  ["On at the mailbox."] = "Ativo na caixa de correio.",
  ["Open all and Gold only buttons in the inbox"] = "Botões Abrir tudo e Só ouro na caixa de entrada",
  ["Two buttons take the place of the game's Open All Mail: Open all takes the gold and items from every mail, Gold only just the gold. Mails with Cash on Delivery and mails from a Game Master are left for you. With full bags the gold is still taken. One line in chat tells what you got."] = "Dois botões substituem o botão do jogo que abre todo o correio: Abrir tudo pega o ouro e os itens de cada carta, Só ouro apenas o ouro. Cartas com pagamento na entrega e de um Mestre de Jogo ficam para você. Com as bolsas cheias, o ouro é pego mesmo assim. Uma linha no bate-papo diz o que você recebeu.",
  ["Recent names beside the To box"] = "Nomes recentes ao lado do destinatário",
  ["A small button at the end of the To box lists the names you sent mail to on this realm and your other characters here. Click one to put it in the To box."] = "Um pequeno botão no fim do campo de destinatário lista os nomes para quem você enviou correio neste reino e seus outros personagens aqui. Clique em um para colocá-lo como destinatário.",
  ["Alt-click a bag item to attach every stack of it"] = "Alt-clique num item da bolsa anexa todas as pilhas dele",
  ["While the Send Mail tab is open, Alt-click an item in your bags and every stack of it goes into the letter, up to its 12 slots. Soulbound items stay in your bags."] = "Com a aba de enviar correio aberta, um Alt-clique num item das suas bolsas coloca todas as pilhas dele na carta, até os 12 espaços dela. Itens vinculados ficam nas suas bolsas.",
  ["Recent names on this realm: %d."] = "Nomes recentes neste reino: %d.",
  ["No recent names on this realm yet."] = "Ainda não há nomes recentes neste reino.",
  ["At the mailbox Codex takes all your mail at once (or only the gold), remembers the names you send mail to, and attaches every stack of an item with one Alt-click. Nothing is sent by itself: you still press Send."] = "Na caixa de correio, o Codex pega todo o seu correio de uma vez (ou só o ouro), lembra os nomes para quem você envia correio e anexa todas as pilhas de um item com um Alt-clique. Nada é enviado sozinho: quem clica em Enviar ainda é você.",
  ["Postal is loaded: it does these jobs, so Codex leaves the mailbox to it."] = "O Postal está carregado: ele já faz essas tarefas, então o Codex deixa a caixa de correio com ele.",
  ["Clears the list of names you sent mail to on this realm. Your characters stay."] = "Limpa a lista de nomes para quem você enviou correio neste reino. Seus personagens ficam.",
})
